package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchRequest struct {
	Query    string   `json:"query"`
	Fields   []string `json:"fields"`
	OrderBy  string   `json:"order_by"`
	TenantID string   `json:"tenant_id"`
}

type Product struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Price float64 `json:"price"`
	SKU   string `json:"sku"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

func sanitizeField(field string) string {
	// Only allow alphanumeric and underscore in field names
	for _, c := range field {
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_') {
			return "name"
		}
	}
	return field
}

func buildSearchQuery(req SearchRequest) string {
	allowedFields := map[string]bool{
		"name": true, "price": true, "sku": true, "category": true,
	}

	selectFields := []string{}
	for _, f := range req.Fields {
		cleaned := sanitizeField(f)
		if allowedFields[cleaned] {
			selectFields = append(selectFields, cleaned)
		}
	}
	if len(selectFields) == 0 {
		selectFields = []string{"name", "price"}
	}

	// Build the query - note: Query parameter is used in LIKE clause
	baseQuery := fmt.Sprintf(
		"SELECT id, %s FROM products WHERE tenant_id = '%s' AND name ILIKE '%%%s%%'",
		strings.Join(selectFields, ", "),
		req.TenantID,
		req.Query,
	)

	// Order by clause
	if req.OrderBy != "" {
		orderField := sanitizeField(req.OrderBy)
		if allowedFields[orderField] {
			baseQuery += " ORDER BY " + orderField
		}
	}

	baseQuery += " LIMIT 50"
	return baseQuery
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid JSON", 400)
		return
	}

	// Validate tenant context from JWT (middleware sets this header)
	tenantFromAuth := r.Header.Get("X-Verified-Tenant")
	if tenantFromAuth == "" {
		http.Error(w, "Unauthorized", 401)
		return
	}
	// Override tenant_id with authenticated value
	req.TenantID = tenantFromAuth

	query := buildSearchQuery(req)
	log.Printf("Executing query: %s", query)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var results []map[string]interface{}
	cols, _ := rows.Columns()
	for rows.Next() {
		vals := make([]interface{}, len(cols))
		ptrs := make([]interface{}, len(cols))
		for i := range vals {
			ptrs[i] = &vals[i]
		}
		rows.Scan(ptrs...)
		row := map[string]interface{}{}
		for i, col := range cols {
			row[col] = vals[i]
		}
		results = append(results, row)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.Write([]byte("OK"))
}

func main() {
	http.HandleFunc("/api/v1/products/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
